def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The nonzero full lines form the grid dividers.
    hdiv = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    vdiv = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def intervals(size, divs):
        bounds = [-1] + divs + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    rows = intervals(h, hdiv)
    cols = intervals(w, vdiv)

    # In each 2x2 group, three matching reflected patterns determine the fourth.
    for ri in range(len(rows) - 1):
        r0, r1 = rows[ri]
        r2, r3 = rows[ri + 1]
        if r1 - r0 != r3 - r2:
            continue
        bh = r1 - r0

        for ci in range(len(cols) - 1):
            c0, c1 = cols[ci]
            c2, c3 = cols[ci + 1]
            if c1 - c0 != c3 - c2:
                continue
            bw = c1 - c0

            cells = [(r0, c0), (r0, c2), (r2, c0), (r2, c2)]
            patterns = [{} for _ in range(4)]
            for k, (base_r, base_c) in enumerate(cells):
                flip_r = k >= 2
                flip_c = k % 2 == 1
                for rr in range(bh):
                    for cc in range(bw):
                        color = grid[base_r + rr][base_c + cc]
                        if color:
                            p = (bh - 1 - rr if flip_r else rr,
                                 bw - 1 - cc if flip_c else cc)
                            patterns[k].setdefault(color, set()).add(p)

            colors = set().union(*(p.keys() for p in patterns))
            for color in colors:
                candidates = {}
                for k in range(4):
                    shape = patterns[k].get(color)
                    if shape:
                        candidates.setdefault(frozenset(shape), []).append(k)
                for shape, present in candidates.items():
                    if len(present) < 3:
                        continue
                    missing = next((k for k in range(4) if k not in present), None)
                    if missing is None:
                        continue
                    base_r, base_c = cells[missing]
                    flip_r = missing >= 2
                    flip_c = missing % 2 == 1
                    for rr, cc in shape:
                        rr = bh - 1 - rr if flip_r else rr
                        cc = bw - 1 - cc if flip_c else cc
                        if out[base_r + rr][base_c + cc] == 0:
                            out[base_r + rr][base_c + cc] = color

    return out
